import crypto from 'crypto';
import type { Db } from '../db/types.js';
import { getDb, getSetting, setSetting } from '../db/index.js';
import { hasProvider } from '../providers/index.js';
import { MEDIA_PLATFORMS, TRANSCRIPTION_PLATFORMS, VIDEO_PLATFORMS } from './media.js';
import { EMBEDDING_PLATFORMS } from './embeddings.js';
import type { Platform } from '@freellmapi/shared/types.js';
import type { Scheduler } from '../lib/scheduler.js';
import {
  applyAllModelOverrides,
  refreshModelOverrideBaselines,
  routableContextWindow,
  applyModelOverrides,
  deleteTombstonedCatalogModels,
  isCatalogModelTombstoned,
  reinstateUpstreamRetiredCatalogModel,
} from './model-state.js';
import { ensureAllModelsInProfiles } from './profile-models.js';

// Generative-media modalities are routed into the separate media_models table
// (see services/media.ts), never into the chat `models` table.
const MEDIA_MODALITIES = new Set(['image', 'audio']);

/**
 * catalog-sync — keeps the local model catalog in step with the published one.
 *
 * Twice a day (and on demand) the server pulls the signed catalog from the
 * catalog service. A valid Premium license key (Bearer) gets the live tier,
 * refreshed every 2-3 days; everyone else gets the monthly snapshot — so free
 * installs still self-heal, just on a slower cadence. The response is verified
 * against a pinned Ed25519 public key over the exact bytes received; anything
 * unsigned or tampered with is discarded, which means a compromised CDN or
 * MITM cannot inject models or quirks into the router.
 *
 * The bundled migrations remain the baseline: a fetched catalog is applied
 * only when it is NEWER than what the binary shipped with (MIN_CATALOG_VERSION
 * below), so a stale monthly snapshot can never roll back models that a newer
 * app version added via migrations.
 */

const DEFAULT_BASE_URL = 'https://api.freellmapi.co';

// The Ed25519 public key the production catalog is signed with. The private
// half was generated on the catalog host and has never left it. Self-hosters
// running their own catalog server can override both via env.
const PINNED_CATALOG_PUBKEY = `-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEAq9yv4+3EeyMHKsfVYBhkcz1lYgIXSUeHNnN6tNgYX3k=
-----END PUBLIC KEY-----
`;

// Catalogs older than this are ignored. Bump to today's date whenever a model
// migration lands, so the bundled DB is always the floor.
export const MIN_CATALOG_VERSION = '2026.06.07';

const SYNC_INTERVAL_MS = 12 * 60 * 60 * 1000; // twice daily
const BOOT_DELAY_MS = 10 * 1000; // let the server settle before first sync
const FETCH_TIMEOUT_MS = 20 * 1000;

// settings table keys
export const SETTING_LICENSE_KEY = 'premium_license_key';
export const SETTING_LICENSE_STATUS = 'premium_license_status'; // JSON LicenseStatus
const SETTING_APPLIED_VERSION = 'catalog_applied_version';
const SETTING_APPLIED_TIER = 'catalog_applied_tier';
const SETTING_APPLIED_JSON = 'catalog_applied_json';
const SETTING_LAST_SYNC_MS = 'catalog_last_sync_ms';
const SETTING_LAST_ERROR = 'catalog_last_error';

export function catalogBaseUrl(): string {
  return (process.env.CATALOG_BASE_URL ?? DEFAULT_BASE_URL).replace(/\/$/, '');
}

function catalogPublicKey(): crypto.KeyObject {
  const pem = process.env.CATALOG_PUBKEY ? process.env.CATALOG_PUBKEY.replace(/\\n/g, '\n') : PINNED_CATALOG_PUBKEY;
  return crypto.createPublicKey({ key: pem, format: 'pem' });
}

export interface LicenseStatus {
  valid: boolean;
  plan: 'annual' | 'lifetime' | null;
  status: string | null;
  expiresAt: string | null;
  cancelAtPeriodEnd?: boolean;
  reason?: string;
  checkedAtMs: number;
}

interface CatalogQuirk {
  slug: string;
  title: string;
  body: string;
  severity: 'blocker' | 'warning' | 'info';
  targets: { platform: string | null; modelGlob: string | null }[];
}

interface CatalogModel {
  platform: string;
  modelId: string;
  displayName: string;
  intelligenceRank: number;
  speedRank: number;
  sizeLabel: string;
  limits: { rpm: number | null; rpd: number | null; tpm: number | null; tpd: number | null };
  monthlyTokenBudget: string | null;
  contextWindow: number | null;
  enabled: boolean;
  supportsVision: boolean;
  supportsTools: boolean;
  /** 'text' (default/absent) routes to the chat `models` table; 'image'/'audio'
   *  route to the separate `media_models` table. */
  modality?: string;
  /** Short display note for media models (e.g. "Keyless - up to 1024x1024"). */
  mediaNote?: string;
  /** Adapter request flavor for media rows, where one platform hosts more than
   *  one deployment style (cloudflare images: absent/'json' = JSON body,
   *  'multipart' = form-data, which the FLUX.2 family requires). Mirrors the
   *  same field on CatalogTranscriptionModel and lands in meta_json. */
  requestStyle?: string | null;
}

interface CatalogEmbedding {
  family: string;
  platform: string;
  modelId: string;
  displayName: string;
  dimensions: number;
  maxInputTokens: number | null;
  priority: number;
  enabled: boolean;
  quotaLabel: string;
}

interface CatalogTranscriptionModel {
  platform: string;
  modelId: string;
  displayName: string;
  /** Failover order within the STT chain, lower first. */
  priority: number;
  enabled: boolean;
  /** Subtitle formats the provider returns natively (e.g. ['vtt']). */
  subtitleFormats?: string[];
  /** Provider upload ceiling in bytes; absent = the route-wide 25 MB cap. */
  maxBytes?: number | null;
  /** Adapter request flavor where one platform hosts more than one deployment
   *  style (cloudflare: 'json' = base64 JSON body, 'binary' = raw bytes). */
  requestStyle?: string | null;
  /** Short display note, mirrored into media_models.quota_label. */
  quotaLabel?: string;
}

interface CatalogVideoModel {
  platform: string;
  modelId: string;
  displayName: string;
  /** Failover order within the video chain, lower first. */
  priority: number;
  enabled: boolean;
  /** Short display note, mirrored into media_models.quota_label. */
  quotaLabel?: string;
  /** Provider-native deployment id when it differs from the public model id
   *  (for example Hugging Face's fal.ai mapping). */
  providerModelId?: string;
}

interface Catalog {
  version: string;
  generatedAt: string;
  tier: 'live' | 'monthly';
  models: CatalogModel[];
  /** Optional for backward compatibility with catalogs published before the
   * embedding registry joined the signed freshness feed. */
  embeddings?: CatalogEmbedding[];
  /** Speech-to-text registry, landing in media_models with
   * modality='transcription'. Deliberately a NEW top-level key rather than
   * more `models` entries: deployed binaries that predate the transcription
   * modality would ingest unknown-modality `models` entries as CHAT models,
   * while an unknown optional key is simply ignored by their isCatalog. */
  transcriptionModels?: CatalogTranscriptionModel[];
  /** Text-to-video registry. Kept out of `models` so pre-video binaries ignore
   *  it rather than routing unknown-modality rows through chat. */
  videoModels?: CatalogVideoModel[];
  /** Platforms the catalog service manages even when this tier ships no rows
   *  for them (#1348): a provider still inside its Premium window, or one the
   *  audit deliberately keeps at zero rows. Names only, never model rows, so
   *  the monthly snapshot can carry it without leaking Premium models. Any
   *  platform listed here is off limits to built-in model discovery. Optional:
   *  older catalogs omit it and older binaries ignore it. */
  managedPlatforms?: string[];
  quirks: CatalogQuirk[];
}

export interface SyncResult {
  ok: boolean;
  action: 'applied' | 'up_to_date' | 'skipped_older' | 'error';
  version?: string;
  tier?: string;
  detail?: string;
  counts?: { updated: number; inserted: number; removed: number; skippedUnknownPlatform: number; quirks: number };
}

/** Minimal structural check — enough to fail loudly on a wrong/garbled body. */
function isCatalog(value: unknown): value is Catalog {
  const c = value as Catalog;
  return (
    !!c &&
    typeof c.version === 'string' &&
    (c.tier === 'live' || c.tier === 'monthly') &&
    Array.isArray(c.models) &&
    Array.isArray(c.quirks) &&
    (c.embeddings === undefined ||
      (Array.isArray(c.embeddings) &&
        c.embeddings.every(
          (m) =>
            typeof m?.family === 'string' &&
            typeof m?.platform === 'string' &&
            typeof m?.modelId === 'string' &&
            typeof m?.displayName === 'string' &&
            typeof m?.dimensions === 'number' &&
            typeof m?.priority === 'number' &&
            typeof m?.enabled === 'boolean',
        ))) &&
    (c.transcriptionModels === undefined ||
      (Array.isArray(c.transcriptionModels) &&
        c.transcriptionModels.every(
          (m) =>
            typeof m?.platform === 'string' &&
            typeof m?.modelId === 'string' &&
            typeof m?.displayName === 'string' &&
            typeof m?.priority === 'number' &&
            typeof m?.enabled === 'boolean' &&
            (m.subtitleFormats === undefined ||
              (Array.isArray(m.subtitleFormats) && m.subtitleFormats.every((f) => typeof f === 'string'))) &&
            (m.maxBytes === undefined || m.maxBytes === null || typeof m.maxBytes === 'number') &&
            (m.requestStyle === undefined || m.requestStyle === null || typeof m.requestStyle === 'string'),
        ))) &&
    (c.videoModels === undefined ||
      (Array.isArray(c.videoModels) &&
        c.videoModels.every(
          (m) =>
            typeof m?.platform === 'string' &&
            typeof m?.modelId === 'string' &&
            typeof m?.displayName === 'string' &&
            typeof m?.priority === 'number' &&
            typeof m?.enabled === 'boolean' &&
            (m.quotaLabel === undefined || typeof m.quotaLabel === 'string') &&
            (m.providerModelId === undefined || typeof m.providerModelId === 'string'),
        ))) &&
    c.models.every(
      (m) =>
        typeof m?.platform === 'string' &&
        typeof m?.modelId === 'string' &&
        typeof m?.displayName === 'string' &&
        typeof m?.enabled === 'boolean' &&
        (m.requestStyle === undefined || m.requestStyle === null || typeof m.requestStyle === 'string') &&
        !!m?.limits &&
        typeof m.limits === 'object',
    ) &&
    (c.managedPlatforms === undefined ||
      (Array.isArray(c.managedPlatforms) && c.managedPlatforms.every((p) => typeof p === 'string'))) &&
    c.quirks.every((q) => typeof q?.slug === 'string' && Array.isArray(q?.targets))
  );
}

/**
 * Apply a verified catalog to the local DB inside one transaction.
 *
 * Rules of engagement with user data:
 *  - metadata (name, ranks, limits, context, capabilities) tracks the catalog
 *    unless the user has an explicit local override;
 *  - catalog enabled=false force-disables (the model is dead upstream), but
 *    enabled=true never re-enables a model the user turned off themselves;
 *  - rows the user created (models.source = 'user': custom providers,
 *    declarative config, admin adds) are never updated, never deleted, and
 *    never adopted — on a platform:model_id collision the user row wins and
 *    the catalog entry is skipped outright;
 *  - catalog models the user deleted stay deleted via tombstones, while models
 *    auto-retired from an upstream 410/end-of-life response (#634) are only
 *    disabled — a catalog that still lists them lifts the retirement;
 *  - models that vanished from the catalog are deleted, exactly like the
 *    dead-model migrations do (fallback_config row first, FK order);
 *  - rows found by built-in model discovery (models.source = 'discovered',
 *    #1348) are a stopgap for platforms the catalog does not manage. The
 *    catalog outranks them: a listed platform:model_id adopts the discovered
 *    row as a catalog row, and once the catalog manages a platform at all,
 *    every other discovered row on it is retired.
 */
/** models.source for rows written by built-in model discovery (#1348). */
export const DISCOVERED_MODEL_SOURCE = 'discovered';

/** Every platform a catalog document manages: any row in any registry, plus
 *  the names-only managedPlatforms list. */
function catalogPlatforms(catalog: Catalog): Set<string> {
  const platforms = new Set<string>();
  for (const m of catalog.models) platforms.add(m.platform);
  for (const m of catalog.embeddings ?? []) platforms.add(m.platform);
  for (const m of catalog.transcriptionModels ?? []) platforms.add(m.platform);
  for (const m of catalog.videoModels ?? []) platforms.add(m.platform);
  for (const p of catalog.managedPlatforms ?? []) platforms.add(p);
  return platforms;
}

let appliedPlatformsCache: { raw: string; platforms: Set<string> } | null = null;

/**
 * Platforms the catalog applied on this install manages (see catalogPlatforms),
 * read from the cached verified document. Empty when no catalog has been
 * applied yet. Built-in model discovery treats every platform in here as off
 * limits, so the audited catalog, not an upstream /models list, decides what
 * those providers serve.
 */
export function appliedCatalogPlatforms(db: Db): Set<string> {
  const row = db.prepare('SELECT value FROM settings WHERE key = ?').get(SETTING_APPLIED_JSON) as { value: string } | undefined;
  const raw = row?.value ?? '';
  if (appliedPlatformsCache && appliedPlatformsCache.raw === raw) return appliedPlatformsCache.platforms;
  let platforms = new Set<string>();
  if (raw) {
    try {
      const parsed: unknown = JSON.parse(raw);
      if (isCatalog(parsed)) platforms = catalogPlatforms(parsed);
    } catch { /* an unreadable cache manages nothing; the DB checks still apply */ }
  }
  appliedPlatformsCache = { raw, platforms };
  return platforms;
}

export function applyCatalog(db: Db, catalog: Catalog): NonNullable<SyncResult['counts']> {
  // One transaction for the whole apply (#1047): the body runs hundreds of
  // individual statements, and under WAL each one outside a transaction is its
  // own commit + fsync executed on the event loop. On slow storage that made
  // the 12-hourly sync freeze every in-flight request — including the 3-query
  // profile-activate POST — for minutes.
  return db.transaction(() => applyCatalogInner(db, catalog))();
}

/**
 * True when this document can say anything we have not already acted on.
 *
 * `reapplyCachedCatalog` deliberately re-applies the very document that is
 * already marked applied — its job is to undo the baseline drift that boot
 * migrations reintroduce. A replay therefore re-presents stale data as if it
 * were a fresh verdict. The fetched path reaches `applyCatalog` only behind
 * `syncCatalog`'s own same-as-applied guard, so for that path the check is
 * always true and nothing changes.
 */
function catalogBringsNewEvidence(catalog: Catalog): boolean {
  return getSetting(SETTING_APPLIED_VERSION) !== catalog.version || getSetting(SETTING_APPLIED_TIER) !== catalog.tier;
}

function applyCatalogInner(db: Db, catalog: Catalog): NonNullable<SyncResult['counts']> {
  const counts = { updated: 0, inserted: 0, removed: 0, skippedUnknownPlatform: 0, quirks: 0 };
  // Read once: the applied-version settings are only written after this
  // transaction returns, so they cannot change underneath the loop.
  const newEvidence = catalogBringsNewEvidence(catalog);

  const selectModel = db.prepare('SELECT id, enabled, source FROM models WHERE platform = ? AND model_id = ?');
  const updateModel = db.prepare(`
    UPDATE models SET
      display_name = @displayName, intelligence_rank = @intelligenceRank, speed_rank = @speedRank,
      size_label = @sizeLabel, rpm_limit = @rpm, rpd_limit = @rpd, tpm_limit = @tpm, tpd_limit = @tpd,
      monthly_token_budget = @monthlyTokenBudget, context_window = @contextWindow,
      supports_vision = @supportsVision, supports_tools = @supportsTools,
      enabled = @enabled
    WHERE id = @id
  `);
  const adoptModel = db.prepare("UPDATE models SET source = 'catalog' WHERE id = ?");
  const insertModel = db.prepare(`
    INSERT INTO models (platform, model_id, display_name, intelligence_rank, speed_rank, size_label,
                        rpm_limit, rpd_limit, tpm_limit, tpd_limit, monthly_token_budget, context_window,
                        enabled, supports_vision, supports_tools, source)
    VALUES (@platform, @modelId, @displayName, @intelligenceRank, @speedRank, @sizeLabel,
            @rpm, @rpd, @tpm, @tpd, @monthlyTokenBudget, @contextWindow,
            @enabled, @supportsVision, @supportsTools, 'catalog')
  `);

  // Generative-media models go to their own table (never the chat router's pool).
  const selectMedia = db.prepare('SELECT id, enabled FROM media_models WHERE platform = ? AND model_id = ?');
  const updateMedia = db.prepare(`
    UPDATE media_models SET
      display_name = @displayName, modality = @modality, priority = @priority,
      quota_label = @quotaLabel, enabled = @enabled, meta_json = @metaJson
    WHERE id = @id
  `);
  const insertMedia = db.prepare(`
    INSERT INTO media_models (platform, model_id, display_name, modality, priority, enabled, quota_label, meta_json)
    VALUES (@platform, @modelId, @displayName, @modality, @priority, @enabled, @quotaLabel, @metaJson)
  `);
  // Transcription rows share media_models but carry adapter metadata in
  // meta_json (subtitle capability, upload ceiling, request flavor).
  const updateTranscription = db.prepare(`
    UPDATE media_models SET
      display_name = @displayName, modality = 'transcription', priority = @priority,
      quota_label = @quotaLabel, enabled = @enabled, meta_json = @metaJson
    WHERE id = @id
  `);
  const insertTranscription = db.prepare(`
    INSERT INTO media_models (platform, model_id, display_name, modality, priority, enabled, quota_label, meta_json)
    VALUES (@platform, @modelId, @displayName, 'transcription', @priority, @enabled, @quotaLabel, @metaJson)
  `);
  const selectEmbedding = db.prepare(
    'SELECT id, enabled FROM embedding_models WHERE platform = ? AND model_id = ?',
  );
  const updateEmbedding = db.prepare(`
    UPDATE embedding_models SET
      family = @family, display_name = @displayName, dimensions = @dimensions,
      max_input_tokens = @maxInputTokens, priority = @priority,
      quota_label = @quotaLabel, enabled = @enabled
    WHERE id = @id
  `);
  const insertEmbedding = db.prepare(`
    INSERT INTO embedding_models
      (family, platform, model_id, display_name, dimensions, max_input_tokens,
       priority, enabled, quota_label)
    VALUES
      (@family, @platform, @modelId, @displayName, @dimensions, @maxInputTokens,
       @priority, @enabled, @quotaLabel)
  `);

  const apply = db.transaction(() => {
    const inCatalog = new Set<string>();
    const inMediaCatalog = new Set<string>();
    const inEmbeddingCatalog = new Set<string>();
    const inTranscriptionCatalog = new Set<string>();
    const inVideoCatalog = new Set<string>();

    for (const m of catalog.models) {
      // Media modalities are gated on MEDIA_PLATFORMS (decoupled from the chat
      // provider registry) and routed to media_models, then skip the chat path.
      const modality = m.modality ?? 'text';
      if (MEDIA_MODALITIES.has(modality)) {
        if (!MEDIA_PLATFORMS.has(m.platform)) {
          counts.skippedUnknownPlatform++;
          continue;
        }
        if (isCatalogModelTombstoned(db, 'media', m.platform, m.modelId)) continue;
        inMediaCatalog.add(`${m.platform}:${m.modelId}`);
        const mrow = selectMedia.get(m.platform, m.modelId) as { id: number; enabled: number } | undefined;
        // Generative-media meta carries only the adapter request flavor today;
        // a row without one stores NULL so the adapter keeps its default.
        const mmeta: Record<string, unknown> = {};
        if (typeof m.requestStyle === 'string') mmeta.requestStyle = m.requestStyle;
        const mfields = {
          displayName: m.displayName,
          modality,
          priority: m.intelligenceRank ?? 0,
          quotaLabel: m.mediaNote ?? '',
          metaJson: Object.keys(mmeta).length > 0 ? JSON.stringify(mmeta) : null,
        };
        if (mrow) {
          const enabled = m.enabled ? mrow.enabled : 0; // catalog disable wins; local disable wins
          updateMedia.run({ ...mfields, id: mrow.id, enabled });
          counts.updated++;
        } else {
          insertMedia.run({ ...mfields, platform: m.platform, modelId: m.modelId, enabled: m.enabled ? 1 : 0 });
          counts.inserted++;
        }
        continue;
      }

      if (m.platform === 'custom' || !hasProvider(m.platform as Platform)) {
        // An older binary may receive models for providers it cannot route yet;
        // skip them — they will appear after the user updates the app.
        counts.skippedUnknownPlatform++;
        continue;
      }
      if (isCatalogModelTombstoned(db, 'chat', m.platform, m.modelId)) continue;
      // A model auto-retired from a 410/end-of-life response (#634) is disabled,
      // not deleted. A catalog that STILL lists it — and lists it enabled — is
      // newer evidence than that one provider response, so lift the retirement.
      // Only for a catalog we have not applied yet: `reapplyCachedCatalog`
      // replays the snapshot the retirement already came after, so replaying it
      // back would clear every retirement on the next boot, however fresh the
      // provider's 410 was.
      if (m.enabled && newEvidence) reinstateUpstreamRetiredCatalogModel(db, m.platform, m.modelId);
      inCatalog.add(`${m.platform}:${m.modelId}`);

      const row = selectModel.get(m.platform, m.modelId) as
        | { id: number; enabled: number; source: string }
        | undefined;
      // Collision rule: if the user hand-added a model and the catalog later
      // ships the same platform:model_id, the user row wins — the catalog
      // neither clobbers its metadata nor adopts it (same spirit as the
      // never-touch rule for custom-provider models). The row also survives
      // the prune below because the delete pass only considers source='catalog'.
      if (row && row.source === 'user') continue;
      // #1348: a DISCOVERED row is the opposite case. Discovery only fills a
      // gap the catalog left, so once the catalog lists the model it takes the
      // row over: the metadata below replaces discovery's guesses and the row
      // becomes catalog-owned (pruned with the catalog from then on). Local
      // disables survive, like on any catalog row.
      if (row && row.source === DISCOVERED_MODEL_SOURCE) adoptModel.run(row.id);
      const fields = {
        displayName: m.displayName,
        intelligenceRank: m.intelligenceRank,
        speedRank: m.speedRank,
        sizeLabel: m.sizeLabel,
        rpm: m.limits.rpm,
        rpd: m.limits.rpd,
        tpm: m.limits.tpm,
        tpd: m.limits.tpd,
        monthlyTokenBudget: m.monthlyTokenBudget,
        contextWindow: routableContextWindow(m.platform, m.modelId, m.contextWindow),
        supportsVision: m.supportsVision ? 1 : 0,
        supportsTools: m.supportsTools ? 1 : 0,
      };
      if (row) {
        // Catalog disable wins (dead upstream); local disable also wins.
        const enabled = m.enabled ? row.enabled : 0;
        updateModel.run({ ...fields, id: row.id, enabled });
        refreshModelOverrideBaselines(db, m.platform, m.modelId);
        applyModelOverrides(db, m.platform, m.modelId);
        counts.updated++;
      } else {
        insertModel.run({ ...fields, platform: m.platform, modelId: m.modelId, enabled: m.enabled ? 1 : 0 });
        refreshModelOverrideBaselines(db, m.platform, m.modelId);
        applyModelOverrides(db, m.platform, m.modelId);
        counts.inserted++;
      }
    }

    // Video models use their own optional full snapshot. Older catalogs omit
    // the key and leave existing video rows untouched; older binaries ignore
    // the key entirely, which is why these rows must not live in models[].
    if (catalog.videoModels) {
      for (const m of catalog.videoModels) {
        if (!VIDEO_PLATFORMS.has(m.platform)) {
          counts.skippedUnknownPlatform++;
          continue;
        }
        if (isCatalogModelTombstoned(db, 'media', m.platform, m.modelId)) continue;
        inVideoCatalog.add(`${m.platform}:${m.modelId}`);
        const meta = typeof m.providerModelId === 'string'
          ? JSON.stringify({ providerModelId: m.providerModelId })
          : null;
        const fields = {
          displayName: m.displayName,
          modality: 'video',
          priority: m.priority,
          quotaLabel: m.quotaLabel ?? '',
          metaJson: meta,
        };
        const row = selectMedia.get(m.platform, m.modelId) as { id: number; enabled: number } | undefined;
        if (row) {
          const enabled = m.enabled ? row.enabled : 0;
          updateMedia.run({ ...fields, id: row.id, enabled });
          counts.updated++;
        } else {
          insertMedia.run({ ...fields, platform: m.platform, modelId: m.modelId, enabled: m.enabled ? 1 : 0 });
          counts.inserted++;
        }
      }
    }

    // Embeddings are their own full snapshot. Older catalogs omit this field;
    // in that case retain the app's bundled embedding baseline untouched.
    if (catalog.embeddings) {
      for (const m of catalog.embeddings) {
        if (!EMBEDDING_PLATFORMS.has(m.platform)) {
          counts.skippedUnknownPlatform++;
          continue;
        }
        inEmbeddingCatalog.add(`${m.platform}:${m.modelId}`);
        const row = selectEmbedding.get(m.platform, m.modelId) as { id: number; enabled: number } | undefined;
        const fields = {
          family: m.family,
          displayName: m.displayName,
          dimensions: m.dimensions,
          maxInputTokens: m.maxInputTokens,
          priority: m.priority,
          quotaLabel: m.quotaLabel,
        };
        if (row) {
          const enabled = m.enabled ? row.enabled : 0; // catalog and local disables both win
          updateEmbedding.run({ ...fields, id: row.id, enabled });
          counts.updated++;
        } else {
          insertEmbedding.run({
            ...fields,
            platform: m.platform,
            modelId: m.modelId,
            enabled: m.enabled ? 1 : 0,
          });
          counts.inserted++;
        }
      }
    }

    // Transcription models are their own full snapshot, routed into
    // media_models with modality='transcription' and gated on
    // TRANSCRIPTION_PLATFORMS the way MEDIA_PLATFORMS gates the generative
    // rows. Older catalogs omit this key; keep existing rows untouched then.
    if (catalog.transcriptionModels) {
      for (const m of catalog.transcriptionModels) {
        if (!TRANSCRIPTION_PLATFORMS.has(m.platform)) {
          counts.skippedUnknownPlatform++;
          continue;
        }
        if (isCatalogModelTombstoned(db, 'media', m.platform, m.modelId)) continue;
        inTranscriptionCatalog.add(`${m.platform}:${m.modelId}`);
        const meta: Record<string, unknown> = {};
        if (m.subtitleFormats?.length) meta.subtitleFormats = m.subtitleFormats;
        if (typeof m.maxBytes === 'number') meta.maxBytes = m.maxBytes;
        if (typeof m.requestStyle === 'string') meta.requestStyle = m.requestStyle;
        const fields = {
          displayName: m.displayName,
          priority: m.priority,
          quotaLabel: m.quotaLabel ?? '',
          metaJson: Object.keys(meta).length > 0 ? JSON.stringify(meta) : null,
        };
        const row = selectMedia.get(m.platform, m.modelId) as { id: number; enabled: number } | undefined;
        if (row) {
          const enabled = m.enabled ? row.enabled : 0; // catalog and local disables both win
          updateTranscription.run({ ...fields, id: row.id, enabled });
          counts.updated++;
        } else {
          insertTranscription.run({ ...fields, platform: m.platform, modelId: m.modelId, enabled: m.enabled ? 1 : 0 });
          counts.inserted++;
        }
      }
    }

    counts.removed += deleteTombstonedCatalogModels(db);
    applyAllModelOverrides(db);

    // Ensure every model has a fallback_config row (same invariant migrations keep).
    const missingFb = db
      .prepare(
        `SELECT m.id FROM models m LEFT JOIN fallback_config f ON m.id = f.model_db_id WHERE f.id IS NULL`,
      )
      .all() as { id: number }[];
    if (missingFb.length > 0) {
      const maxPriority = (db.prepare('SELECT COALESCE(MAX(priority), 0) AS mx FROM fallback_config').get() as { mx: number }).mx;
      const addFb = db.prepare('INSERT INTO fallback_config (model_db_id, priority, enabled) VALUES (?, ?, 1)');
      missingFb.forEach((r, i) => addFb.run(r.id, maxPriority + 1 + i));
    }
    ensureAllModelsInProfiles(db);

    // Remove catalog-managed models that the catalog no longer lists.
    // Ownership is decided by the `source` provenance column: only rows the
    // catalog itself created are prune candidates. Rows with source='user'
    // (declarative config, admin adds, custom endpoints) are never deleted
    // here, no matter what their size_label or platform says — that replaces
    // the old size_label NOT IN ('User','Custom') heuristic, which lost user
    // rows whose label didn't follow the convention. The platform/key_id
    // predicates stay as belt and braces.
    const candidates = db
      .prepare(`
        SELECT id, platform, model_id
          FROM models
         WHERE platform != 'custom'
           AND key_id IS NULL
           AND source = 'catalog'
      `)
      .all() as { id: number; platform: string; model_id: string }[];
    const deleteFb = db.prepare('DELETE FROM fallback_config WHERE model_db_id = ?');
    const deleteModel = db.prepare('DELETE FROM models WHERE id = ?');
    for (const c of candidates) {
      if (!hasProvider(c.platform as Platform)) continue; // not catalog-managed by this binary
      if (!inCatalog.has(`${c.platform}:${c.model_id}`)) {
        deleteFb.run(c.id);
        deleteModel.run(c.id);
        counts.removed++;
      }
    }

    // #1348: retire discovered rows on every platform the catalog now
    // manages. A platform counts as managed when this catalog carries ANY row
    // for it (chat, media, embedding, STT or video; enabled or disabled, since
    // a disabled row is still an audit verdict) or names it in
    // managedPlatforms. Rows the catalog listed were adopted above and are
    // source='catalog' by now, so what is left is exactly the discovered
    // stopgap the catalog has superseded.
    const managed = catalogPlatforms(catalog);
    const discoveredRows = db
      .prepare('SELECT id, platform FROM models WHERE source = ?')
      .all(DISCOVERED_MODEL_SOURCE) as { id: number; platform: string }[];
    for (const d of discoveredRows) {
      if (!managed.has(d.platform)) continue;
      deleteFb.run(d.id);
      deleteModel.run(d.id);
      counts.removed++;
    }

    // Remove media models the catalog no longer lists (own table, no
    // fallback_config). Deliberately an ALLOWLIST of the two modalities that
    // `models[]` maintains, not "everything except transcription": video and
    // transcription rows come from their own optional snapshots below, so a
    // catalog that omits those keys must leave them alone. Widening this back
    // to a `!=` filter would silently delete every video row on the first sync
    // from an older catalog.
    const mediaCandidates = db
      .prepare("SELECT id, platform, model_id FROM media_models WHERE modality IN ('image', 'audio')")
      .all() as { id: number; platform: string; model_id: string }[];
    const deleteMedia = db.prepare('DELETE FROM media_models WHERE id = ?');
    for (const c of mediaCandidates) {
      if (!MEDIA_PLATFORMS.has(c.platform)) continue; // not media-managed by this binary
      if (!inMediaCatalog.has(`${c.platform}:${c.model_id}`)) {
        deleteMedia.run(c.id);
        counts.removed++;
      }
    }

    // Prune video rows only when this catalog actually carries the dedicated
    // snapshot. An older catalog cannot know whether a video row was retired.
    if (catalog.videoModels) {
      const videoCandidates = db
        .prepare("SELECT id, platform, model_id FROM media_models WHERE modality = 'video'")
        .all() as { id: number; platform: string; model_id: string }[];
      for (const c of videoCandidates) {
        if (!VIDEO_PLATFORMS.has(c.platform)) continue;
        if (!inVideoCatalog.has(`${c.platform}:${c.model_id}`)) {
          deleteMedia.run(c.id);
          counts.removed++;
        }
      }
    }

    // Prune transcription rows only when the catalog actually carries the
    // snapshot (mirrors the embeddings rule), scoped to the modality so
    // image/audio rows are never touched by it.
    if (catalog.transcriptionModels) {
      const sttCandidates = db
        .prepare("SELECT id, platform, model_id FROM media_models WHERE modality = 'transcription'")
        .all() as { id: number; platform: string; model_id: string }[];
      for (const c of sttCandidates) {
        if (!TRANSCRIPTION_PLATFORMS.has(c.platform)) continue;
        if (!inTranscriptionCatalog.has(`${c.platform}:${c.model_id}`)) {
          deleteMedia.run(c.id);
          counts.removed++;
        }
      }
    }

    // Embeddings are their own full snapshot. Older catalogs omit this field,
    // AND catalogs may publish `embeddings: []` while still shipping model
    // rows — both cases mean "retain the app's bundled embedding baseline
    // untouched". The JS truthy check on a non-empty array object would
    // misfire on `[]`, wiping the seeded rows; gate on length instead.
    if (catalog.embeddings && catalog.embeddings.length > 0) {
      const embeddingCandidates = db
        .prepare(`
          SELECT id, platform, model_id
            FROM embedding_models
           WHERE platform != 'custom' AND key_id IS NULL
        `)
        .all() as { id: number; platform: string; model_id: string }[];
      const deleteEmbedding = db.prepare('DELETE FROM embedding_models WHERE id = ?');
      for (const c of embeddingCandidates) {
        if (!EMBEDDING_PLATFORMS.has(c.platform)) continue;
        if (!inEmbeddingCatalog.has(`${c.platform}:${c.model_id}`)) {
          deleteEmbedding.run(c.id);
          counts.removed++;
        }
      }
    }

    // Quirks are pure content: replace wholesale.
    db.prepare('DELETE FROM quirk_targets').run();
    db.prepare('DELETE FROM quirks').run();
    const insertQuirk = db.prepare(
      `INSERT INTO quirks (slug, title, body, severity, created_at_ms, updated_at_ms) VALUES (?, ?, ?, ?, ?, ?)`,
    );
    const insertTarget = db.prepare(
      `INSERT INTO quirk_targets (quirk_id, platform, model_glob) VALUES (?, ?, ?)`,
    );
    const now = Date.now();
    for (const q of catalog.quirks) {
      const info = insertQuirk.run(q.slug, q.title, q.body, q.severity, now, now);
      for (const t of q.targets) insertTarget.run(info.lastInsertRowid, t.platform ?? null, t.modelGlob ?? null);
      counts.quirks++;
    }
  });

  apply();
  return counts;
}

/**
 * Fetch the catalog, verify its signature, and apply it if it moves us forward.
 * `force` skips the `since` short-circuit — used right after a license key is
 * added or removed, where the tier can change without the version changing.
 */
export async function syncCatalog(force = false): Promise<SyncResult> {
  const db = getDb();
  const key = getSetting(SETTING_LICENSE_KEY);
  const applied = getSetting(SETTING_APPLIED_VERSION);

  try {
    const headers: Record<string, string> = {};
    if (key) headers.Authorization = `Bearer ${key}`;
    const url = new URL(`${catalogBaseUrl()}/v1/latest`);
    if (applied && !force) url.searchParams.set('since', applied);

    const res = await fetch(url, { headers, signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });

    if (res.status === 304) {
      setSetting(SETTING_LAST_SYNC_MS, String(Date.now()));
      setSetting(SETTING_LAST_ERROR, '');
      return { ok: true, action: 'up_to_date', version: applied };
    }
    if (!res.ok) throw new Error(`catalog fetch failed: HTTP ${res.status}`);

    const signature = res.headers.get('x-catalog-signature');
    if (!signature) throw new Error('catalog response missing signature');
    const bytes = Buffer.from(await res.arrayBuffer());
    const verified = crypto.verify(null, bytes, catalogPublicKey(), Buffer.from(signature, 'base64'));
    if (!verified) throw new Error('catalog signature verification FAILED — discarding response');

    const parsed: unknown = JSON.parse(bytes.toString('utf8'));
    if (!isCatalog(parsed)) throw new Error('catalog payload has unexpected shape');
    const catalog = parsed;

    if (catalog.version < MIN_CATALOG_VERSION) {
      // Older than the bundled baseline (e.g. monthly snapshot lagging a fresh
      // app release) — applying it would roll back migrations. Wait it out.
      setSetting(SETTING_LAST_SYNC_MS, String(Date.now()));
      setSetting(SETTING_LAST_ERROR, '');
      return { ok: true, action: 'skipped_older', version: catalog.version, tier: catalog.tier };
    }

    const sameAsApplied = applied === catalog.version && getSetting(SETTING_APPLIED_TIER) === catalog.tier;
    if (!sameAsApplied) {
      const counts = applyCatalog(db, catalog);
      setSetting(SETTING_APPLIED_VERSION, catalog.version);
      setSetting(SETTING_APPLIED_TIER, catalog.tier);
      // Cache the verified document so boots can re-apply it offline (see
      // reapplyCachedCatalog). Stored post-verification: anything that could
      // tamper this row could tamper the models table directly, so the cache
      // adds no new trust surface.
      setSetting(SETTING_APPLIED_JSON, bytes.toString('utf8'));
      console.log(
        `[catalog-sync] applied ${catalog.tier} v${catalog.version}: ` +
          `${counts.updated} updated, ${counts.inserted} new, ${counts.removed} removed, ` +
          `${counts.quirks} quirks` +
          (counts.skippedUnknownPlatform ? `, ${counts.skippedUnknownPlatform} skipped (unknown platform)` : ''),
      );
      setSetting(SETTING_LAST_SYNC_MS, String(Date.now()));
      setSetting(SETTING_LAST_ERROR, '');
      return { ok: true, action: 'applied', version: catalog.version, tier: catalog.tier, counts };
    }

    setSetting(SETTING_LAST_SYNC_MS, String(Date.now()));
    setSetting(SETTING_LAST_ERROR, '');
    return { ok: true, action: 'up_to_date', version: catalog.version, tier: catalog.tier };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    console.warn(`[catalog-sync] ${message}`);
    setSetting(SETTING_LAST_ERROR, message);
    return { ok: false, action: 'error', detail: message };
  }
}

/** Raw response from the catalog service's license activation endpoint. */
export interface LicenseActivation {
  valid: boolean;
  plan: string | null;
  status: string | null;
  expiresAt: string | null;
  reason?: string;
}

/**
 * Validate a key with the license service. Returns null when the service is
 * unreachable — distinguishable from a rejected key, so a transient outage can
 * be warned about instead of reported as a bad key. Shared by the dashboard's
 * POST /api/premium/key and declarative `license` config.
 */
export async function validateLicenseKey(key: string, timeoutMs = FETCH_TIMEOUT_MS): Promise<LicenseActivation | null> {
  try {
    const res = await fetch(`${catalogBaseUrl()}/v1/license/activate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ key }),
      signal: AbortSignal.timeout(timeoutMs),
    });
    return (await res.json()) as LicenseActivation;
  } catch {
    return null;
  }
}

/** Revalidate the stored license against the catalog service and cache the result. */
export async function refreshLicenseStatus(): Promise<LicenseStatus | null> {
  const key = getSetting(SETTING_LICENSE_KEY);
  if (!key) return null;
  try {
    const res = await fetch(`${catalogBaseUrl()}/v1/license/check`, {
      headers: { Authorization: `Bearer ${key}` },
      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
    });
    if (!res.ok && res.status !== 401) throw new Error(`HTTP ${res.status}`);
    const body = (await res.json()) as Omit<LicenseStatus, 'checkedAtMs'>;
    const status: LicenseStatus = { ...body, checkedAtMs: Date.now() };
    setSetting(SETTING_LICENSE_STATUS, JSON.stringify(status));
    return status;
  } catch (err) {
    // Offline or service down: keep the cached status. Entitlement is enforced
    // server-side at /v1/latest anyway — this cache is informational UI state.
    console.warn(`[catalog-sync] license check unreachable: ${err instanceof Error ? err.message : err}`);
    return getCachedLicenseStatus();
  }
}

export function getCachedLicenseStatus(): LicenseStatus | null {
  const raw = getSetting(SETTING_LICENSE_STATUS);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as LicenseStatus;
  } catch {
    return null;
  }
}

export interface CatalogSyncState {
  baseUrl: string;
  appliedVersion: string | null;
  appliedTier: string | null;
  lastSyncMs: number | null;
  lastError: string | null;
}

export function getSyncState(): CatalogSyncState {
  return {
    baseUrl: catalogBaseUrl(),
    appliedVersion: getSetting(SETTING_APPLIED_VERSION) ?? null,
    appliedTier: getSetting(SETTING_APPLIED_TIER) ?? null,
    lastSyncMs: Number(getSetting(SETTING_LAST_SYNC_MS)) || null,
    lastError: getSetting(SETTING_LAST_ERROR) || null,
  };
}

/**
 * Re-apply the cached (already signature-verified) catalog after boot.
 *
 * Migrations run on every boot and re-assert the bundled baseline — they
 * INSERT OR IGNORE baseline models the catalog may have deleted and re-run
 * the family-rule resets — while the boot-time network sync 304s on an
 * unchanged version and so would NOT re-apply. Without this step every
 * restart drifts the DB back toward the baseline until the next catalog
 * version bump. Re-applying from the local cache is synchronous, needs no
 * network, and keeps the catalog authoritative even offline.
 *
 * Legacy upgrade path: installs that applied a catalog before the cache
 * existed have an applied-version setting but no cached document. Clearing
 * the applied version makes the next poll fetch the full catalog (no `since`
 * short-circuit), which re-applies it and populates the cache.
 */
export function reapplyCachedCatalog(): { reapplied: boolean; version?: string } {
  try {
    const raw = getSetting(SETTING_APPLIED_JSON);
    if (!raw) {
      if (getSetting(SETTING_APPLIED_VERSION)) {
        getDb().prepare('DELETE FROM settings WHERE key = ?').run(SETTING_APPLIED_VERSION);
      }
      return { reapplied: false };
    }
    const parsed: unknown = JSON.parse(raw);
    if (!isCatalog(parsed) || parsed.version < MIN_CATALOG_VERSION) return { reapplied: false };
    applyCatalog(getDb(), parsed);
    console.log(`[catalog-sync] re-applied cached ${parsed.tier} v${parsed.version} after boot`);
    return { reapplied: true, version: parsed.version };
  } catch (err) {
    console.warn(`[catalog-sync] cached catalog re-apply failed: ${err instanceof Error ? err.message : err}`);
    return { reapplied: false };
  }
}

let cancelBootTimer: (() => void) | null = null;
let cancelInterval: (() => void) | null = null;

export function startCatalogSync(scheduler: Scheduler): void {
  if (cancelInterval) return;
  if (process.env.CATALOG_SYNC_DISABLED === '1') {
    console.log('[catalog-sync] disabled via CATALOG_SYNC_DISABLED=1');
    return;
  }
  reapplyCachedCatalog();
  const run = () => {
    void refreshLicenseStatus();
    void syncCatalog();
  };
  cancelBootTimer = scheduler.after(BOOT_DELAY_MS, run);
  cancelInterval = scheduler.every(SYNC_INTERVAL_MS, run);
  console.log(`[catalog-sync] polling ${catalogBaseUrl()} every ${SYNC_INTERVAL_MS / 3600000}h`);
}

export function stopCatalogSync(): void {
  if (cancelBootTimer) {
    cancelBootTimer();
    cancelBootTimer = null;
  }
  if (cancelInterval) {
    cancelInterval();
    cancelInterval = null;
  }
}

import type { Db } from '../db/types.js';
import type { applyCatalog } from './catalog-sync.js';

export type CatalogModelKind = 'chat' | 'media';

export interface ModelOverridePatch {
  displayName?: string;
  intelligenceRank?: number;
  speedRank?: number;
  sizeLabel?: string;
  rpmLimit?: number | null;
  rpdLimit?: number | null;
  tpmLimit?: number | null;
  tpdLimit?: number | null;
  monthlyTokenBudget?: string;
  contextWindow?: number | null;
  supportsVision?: boolean;
  supportsTools?: boolean;
  enabled?: boolean;
}

type StoredOverrides = Partial<ModelOverridePatch>;

// Keep catalog values separately from effective local edits. Legacy blobs
// recover their defaults from the verified catalog cache; catalog sync refreshes
// recorded baselines before reapplying overrides. Unknown defaults stay unknown.
const CATALOG_BASELINE_KEY = 'catalogDefaults';

const OVERRIDE_COLUMNS: Record<keyof ModelOverridePatch, string> = {
  displayName: 'display_name',
  intelligenceRank: 'intelligence_rank',
  speedRank: 'speed_rank',
  sizeLabel: 'size_label',
  rpmLimit: 'rpm_limit',
  rpdLimit: 'rpd_limit',
  tpmLimit: 'tpm_limit',
  tpdLimit: 'tpd_limit',
  monthlyTokenBudget: 'monthly_token_budget',
  contextWindow: 'context_window',
  supportsVision: 'supports_vision',
  supportsTools: 'supports_tools',
  enabled: 'enabled',
};

function parseOverrides(raw: string | undefined): StoredOverrides {
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as unknown;
    return parsed && typeof parsed === 'object' ? parsed as StoredOverrides : {};
  } catch {
    return {};
  }
}

function toDbValue(key: keyof ModelOverridePatch, value: unknown): unknown {
  if (key === 'supportsVision' || key === 'supportsTools' || key === 'enabled') return value ? 1 : 0;
  return value;
}

function cleanPatch(patch: ModelOverridePatch): StoredOverrides {
  const cleaned: StoredOverrides = {};
  for (const key of Object.keys(OVERRIDE_COLUMNS) as Array<keyof ModelOverridePatch>) {
    if (Object.prototype.hasOwnProperty.call(patch, key)) {
      cleaned[key] = patch[key] as never;
    }
  }
  return cleaned;
}

// The blob split into its two parts: the fields actually overridden, and the
// pre-override values they are measured against.
function parseOverridesBlob(raw: string | undefined): { overrides: StoredOverrides; baselines: StoredOverrides } {
  const overrides = { ...parseOverrides(raw) };
  const rawBaselines = (overrides as Record<string, unknown>)[CATALOG_BASELINE_KEY];
  delete (overrides as Record<string, unknown>)[CATALOG_BASELINE_KEY];
  const baselines: StoredOverrides = {};
  if (rawBaselines && typeof rawBaselines === 'object') {
    for (const key of Object.keys(rawBaselines as Record<string, unknown>) as Array<keyof ModelOverridePatch>) {
      if (key in OVERRIDE_COLUMNS) baselines[key] = (rawBaselines as StoredOverrides)[key] as never;
    }
  }
  return { overrides, baselines };
}

// Convert a catalog-applied database value into the PATCH representation.
function modelRowValue(row: Record<string, unknown> | undefined, key: keyof ModelOverridePatch): unknown {
  if (!row) return undefined;
  const value = row[OVERRIDE_COLUMNS[key]];
  if (key === 'supportsVision' || key === 'supportsTools' || key === 'enabled') return value === 1;
  return value ?? null;
}

export function routableContextWindow(platform: string, modelId: string, contextWindow: number | null): number | null {
  if (platform === 'github' && modelId === 'openai/gpt-4.1') return 8000;
  return contextWindow;
}

function cachedCatalogDefaults(db: Db, platform: string, modelId: string): StoredOverrides {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'catalog_applied_json'").get() as { value: string } | undefined;
  if (!row) return {};
  try {
    const catalog = JSON.parse(row.value) as { models?: Parameters<typeof applyCatalog>[1]['models'] };
    const model = catalog.models?.find(m => m.platform === platform && m.modelId === modelId && (!m.modality || m.modality === 'text'));
    if (!model?.limits) return {};
    return {
      displayName: model.displayName, intelligenceRank: model.intelligenceRank,
      speedRank: model.speedRank, sizeLabel: model.sizeLabel,
      rpmLimit: model.limits.rpm, rpdLimit: model.limits.rpd,
      tpmLimit: model.limits.tpm, tpdLimit: model.limits.tpd,
      monthlyTokenBudget: model.monthlyTokenBudget ?? '',
      contextWindow: routableContextWindow(platform, modelId, model.contextWindow),
      supportsVision: model.supportsVision, supportsTools: model.supportsTools,
      enabled: model.enabled,
    };
  } catch { return {}; }
}

/** Called after catalog metadata is written, before local overrides are applied. */
export function refreshModelOverrideBaselines(db: Db, platform: string, modelId: string): void {
  const existing = db.prepare('SELECT overrides_json FROM model_overrides WHERE platform = ? AND model_id = ?')
    .get(platform, modelId) as { overrides_json: string } | undefined;
  if (!existing) return;
  const { overrides } = parseOverridesBlob(existing.overrides_json);
  const row = db.prepare('SELECT * FROM models WHERE platform = ? AND model_id = ?').get(platform, modelId) as Record<string, unknown> | undefined;
  const baselines: StoredOverrides = {};
  for (const key of Object.keys(cleanPatch(overrides)) as Array<keyof ModelOverridePatch>) {
    const value = modelRowValue(row, key);
    if (value !== undefined) baselines[key] = value as never;
  }
  db.prepare('UPDATE model_overrides SET overrides_json = ? WHERE platform = ? AND model_id = ?')
    .run(JSON.stringify({ ...overrides, [CATALOG_BASELINE_KEY]: baselines }), platform, modelId);
}

/**
 * The fields a stored overrides blob actually overrides, for callers that
 * already selected `model_overrides.overrides_json` alongside the model row.
 * The dashboard uses this to mark individual inputs as locally overridden
 * instead of flagging the whole model (#551).
 */
export function overriddenFieldNames(overridesJson: string | null | undefined): Array<keyof ModelOverridePatch> {
  const stored = parseOverrides(overridesJson ?? undefined);
  return (Object.keys(stored) as Array<keyof ModelOverridePatch>).filter(key => key in OVERRIDE_COLUMNS);
}

export function isCatalogManagedModel(row: { platform: string; key_id?: number | null; source?: string }): boolean {
  // `source` is the authoritative provenance (models.source: 'catalog', 'user'
  // or 'discovered'). Discovered rows on built-in platforms (#1348) count as
  // catalog-managed: deleting one records a catalog tombstone, which both
  // discovery and a later catalog honor;
  // callers that select it get an exact answer. The platform/key_id fallback
  // covers callers that don't have the column in hand.
  if (row.source === 'user') return false;
  return row.platform !== 'custom' && row.key_id == null;
}

// Why a catalog model carries a tombstone:
//   'user'        — deleted in the dashboard. Stays deleted across syncs, and
//                   the row is removed from `models` on the next catalog apply.
//   'upstream_eol' — the provider reported it permanently gone (410 / end of
//                   life, issue #634). The row SURVIVES and is only disabled,
//                   so the dashboard can show "retired upstream" instead of
//                   silently losing the model, and so a later catalog that
//                   still lists it can lift the retirement.
export type CatalogTombstoneSource = 'user' | 'upstream_eol';

export interface CatalogModelTombstone {
  source: CatalogTombstoneSource;
  reason: string | null;
  createdAt: string;
}

export function getCatalogModelTombstone(
  db: Db,
  kind: CatalogModelKind,
  platform: string,
  modelId: string,
): CatalogModelTombstone | undefined {
  const row = db
    .prepare('SELECT source, reason, created_at FROM catalog_model_tombstones WHERE kind = ? AND platform = ? AND model_id = ?')
    .get(kind, platform, modelId) as { source: string; reason: string | null; created_at: string } | undefined;
  if (!row) return undefined;
  return {
    source: row.source === 'upstream_eol' ? 'upstream_eol' : 'user',
    reason: row.reason ?? null,
    createdAt: row.created_at,
  };
}

/**
 * True only for models the USER deleted — the "keep it deleted" contract every
 * caller here means. An upstream-retirement tombstone deliberately does NOT
 * count: those models stay in the catalog's write path so a refreshed catalog
 * can reinstate them (see reinstateUpstreamRetiredCatalogModel).
 */
export function isCatalogModelTombstoned(
  db: Db,
  kind: CatalogModelKind,
  platform: string,
  modelId: string,
): boolean {
  return getCatalogModelTombstone(db, kind, platform, modelId)?.source === 'user';
}

export function recordCatalogModelTombstone(
  db: Db,
  kind: CatalogModelKind,
  platform: string,
  modelId: string,
  options: { source?: CatalogTombstoneSource; reason?: string | null } = {},
): void {
  const source: CatalogTombstoneSource = options.source ?? 'user';
  db.prepare(`
    INSERT INTO catalog_model_tombstones (kind, platform, model_id, source, reason)
    VALUES (?, ?, ?, ?, ?)
    ON CONFLICT(kind, platform, model_id)
    DO UPDATE SET created_at = datetime('now'), source = excluded.source, reason = excluded.reason
  `).run(kind, platform, modelId, source, options.reason ?? null);
  // A user deletion drops their local metadata edits with the row. An upstream
  // retirement keeps the row, so it keeps the overrides too — they must survive
  // if the model is reinstated.
  if (kind === 'chat' && source === 'user') {
    db.prepare('DELETE FROM model_overrides WHERE platform = ? AND model_id = ?').run(platform, modelId);
  }
}

/**
 * Auto-disable a catalog model the provider reports as permanently retired
 * (issue #634). Deliberately NOT a delete: the row stays visible in the
 * dashboard, tagged with the upstream wording, and the user can flip it back on
 * if they disagree. Turning off the chain entries (and the active profile's
 * copy) is exactly what the dashboard's own switch does, so the router stops
 * picking it while an explicitly-requested model id still resolves.
 *
 * Returns true when this call performed the retirement (false when it was
 * already retired, or the user had deleted the model outright).
 */
export function retireCatalogModelUpstream(
  db: Db,
  modelDbId: number,
  platform: string,
  modelId: string,
  reason: string,
): boolean {
  const existing = getCatalogModelTombstone(db, 'chat', platform, modelId);
  if (existing) return false;
  recordCatalogModelTombstone(db, 'chat', platform, modelId, { source: 'upstream_eol', reason });
  db.prepare('UPDATE fallback_config SET enabled = 0 WHERE model_db_id = ?').run(modelDbId);
  db.prepare('UPDATE profile_models SET enabled = 0 WHERE model_db_id = ?').run(modelDbId);
  return true;
}

/**
 * Lift an upstream retirement: a catalog that still lists the model — and lists
 * it enabled — is newer and better evidence than one provider's 404. Returns
 * true when a retirement was actually lifted.
 */
export function reinstateUpstreamRetiredCatalogModel(
  db: Db,
  platform: string,
  modelId: string,
): boolean {
  if (getCatalogModelTombstone(db, 'chat', platform, modelId)?.source !== 'upstream_eol') return false;
  clearCatalogModelTombstone(db, 'chat', platform, modelId);
  const row = db
    .prepare('SELECT id FROM models WHERE platform = ? AND model_id = ?')
    .get(platform, modelId) as { id: number } | undefined;
  if (row) {
    db.prepare('UPDATE fallback_config SET enabled = 1 WHERE model_db_id = ?').run(row.id);
    db.prepare('UPDATE profile_models SET enabled = 1 WHERE model_db_id = ?').run(row.id);
  }
  return true;
}

export function clearCatalogModelTombstone(
  db: Db,
  kind: CatalogModelKind,
  platform: string,
  modelId: string,
): void {
  db.prepare('DELETE FROM catalog_model_tombstones WHERE kind = ? AND platform = ? AND model_id = ?')
    .run(kind, platform, modelId);
}

export function upsertModelOverrides(
  db: Db,
  platform: string,
  modelId: string,
  patch: ModelOverridePatch,
  options: { baselineRow?: Record<string, unknown> } = {},
): StoredOverrides {
  const cleaned = cleanPatch(patch);
  if (Object.keys(cleaned).length === 0) return {};
  const existing = db
    .prepare('SELECT overrides_json FROM model_overrides WHERE platform = ? AND model_id = ?')
    .get(platform, modelId) as { overrides_json: string } | undefined;
  const { overrides: stored, baselines } = parseOverridesBlob(existing?.overrides_json);

  const catalogDefaults = options.baselineRow ? cachedCatalogDefaults(db, platform, modelId) : {};
  const merged: StoredOverrides = { ...stored };
  const mergedBaselines: StoredOverrides = { ...baselines };
  for (const key of Object.keys(cleaned) as Array<keyof ModelOverridePatch>) {
    const next = cleaned[key] as never;
    if (mergedBaselines[key] === undefined && options.baselineRow) {
      // An old override is already applied to the row. Never mistake that
      // effective value for the catalog value during an upgrade.
      const captured = catalogDefaults[key] !== undefined ? catalogDefaults[key]
        : stored[key] === undefined ? modelRowValue(options.baselineRow, key) : undefined;
      if (captured !== undefined) mergedBaselines[key] = captured as never;
    }
    const baseline = mergedBaselines[key];
    if (options.baselineRow && baseline !== undefined && next === baseline) {
      // Back at the pre-override value: the override (and its baseline) drop
      // out, so the field tracks the catalog again.
      delete merged[key];
      delete mergedBaselines[key];
    } else {
      merged[key] = next;
    }
  }

  if (Object.keys(merged).length === 0) {
    // Nothing left to pin: drop the row so has_overrides goes false and the
    // dashboard's badge clears.
    db.prepare('DELETE FROM model_overrides WHERE platform = ? AND model_id = ?').run(platform, modelId);
    return {};
  }
  const blob = { ...merged, [CATALOG_BASELINE_KEY]: mergedBaselines };
  db.prepare(`
    INSERT INTO model_overrides (platform, model_id, overrides_json, updated_at)
    VALUES (?, ?, ?, datetime('now'))
    ON CONFLICT(platform, model_id)
    DO UPDATE SET overrides_json = excluded.overrides_json, updated_at = excluded.updated_at
  `).run(platform, modelId, JSON.stringify(blob));
  return merged;
}

export function getModelOverrides(
  db: Db,
  platform: string,
  modelId: string,
): StoredOverrides {
  const row = db
    .prepare('SELECT overrides_json FROM model_overrides WHERE platform = ? AND model_id = ?')
    .get(platform, modelId) as { overrides_json: string } | undefined;
  return parseOverrides(row?.overrides_json);
}

/**
 * Every model whose stored overrides pin ONE given field, as a set of
 * "platform:model_id" keys. One query over a table that only ever holds the
 * models a user has actually touched, so callers that need "is this field
 * user-owned?" for a whole catalog don't do it per model.
 *
 * Note it keys off the field, not the row: a user who renamed a model has an
 * override row but has said nothing about its speed_rank, so a derived value
 * may still fill that column (#619).
 */
export function modelsWithOverriddenField(
  db: Db,
  field: keyof ModelOverridePatch,
): Set<string> {
  const rows = db.prepare('SELECT platform, model_id, overrides_json FROM model_overrides')
    .all() as { platform: string; model_id: string; overrides_json: string }[];
  const pinned = new Set<string>();
  for (const row of rows) {
    const overrides = parseOverrides(row.overrides_json);
    if (overrides[field] !== undefined) pinned.add(`${row.platform}:${row.model_id}`);
  }
  return pinned;
}

export function applyModelOverrides(
  db: Db,
  platform: string,
  modelId: string,
): boolean {
  const overrides = getModelOverrides(db, platform, modelId);
  const keys = (Object.keys(overrides) as Array<keyof ModelOverridePatch>).filter(k => k in OVERRIDE_COLUMNS);
  if (keys.length === 0) return false;

  const assignments: string[] = [];
  const values: unknown[] = [];
  for (const key of keys) {
    assignments.push(`${OVERRIDE_COLUMNS[key]} = ?`);
    values.push(toDbValue(key, overrides[key]));
  }
  values.push(platform, modelId);
  db.prepare(`UPDATE models SET ${assignments.join(', ')} WHERE platform = ? AND model_id = ?`).run(...values);
  return true;
}

export function applyAllModelOverrides(db: Db): number {
  const rows = db.prepare('SELECT platform, model_id FROM model_overrides').all() as { platform: string; model_id: string }[];
  let applied = 0;
  for (const row of rows) {
    if (applyModelOverrides(db, row.platform, row.model_id)) applied++;
  }
  return applied;
}

// Only USER tombstones delete rows. An upstream-retirement tombstone disables
// its model and keeps it (see retireCatalogModelUpstream), so deleting here
// would throw away both the row and the reason the dashboard shows for it.
export function deleteTombstonedCatalogModels(db: Db): number {
  const chatRows = db.prepare(`
    SELECT m.id, m.platform, m.model_id
      FROM models m
      JOIN catalog_model_tombstones t
        ON t.kind = 'chat' AND t.platform = m.platform AND t.model_id = m.model_id
     WHERE t.source = 'user' AND m.platform != 'custom' AND m.key_id IS NULL AND m.source != 'user'
  `).all() as { id: number; platform: string; model_id: string }[];
  const mediaRows = db.prepare(`
    SELECT mm.id
      FROM media_models mm
      JOIN catalog_model_tombstones t
        ON t.kind = 'media' AND t.platform = mm.platform AND t.model_id = mm.model_id
     WHERE t.source = 'user'
  `).all() as { id: number }[];

  const deleteChatFallback = db.prepare('DELETE FROM fallback_config WHERE model_db_id = ?');
  const deleteChat = db.prepare('DELETE FROM models WHERE id = ?');
  const deleteMedia = db.prepare('DELETE FROM media_models WHERE id = ?');

  for (const row of chatRows) {
    deleteChatFallback.run(row.id);
    deleteChat.run(row.id);
  }
  for (const row of mediaRows) {
    deleteMedia.run(row.id);
  }

  return chatRows.length + mediaRows.length;
}

import type {
  ChatMessage,
  ChatCompletionResponse,
  ChatCompletionChunk,
  ChatToolDefinition,
  ChatToolChoice,
  Platform,
} from '@freellmapi/shared/types.js';
import type { QuotaObservationContext } from '../services/provider-quota.js';
import type { ExtendedSamplingOptions } from '../lib/sampling-params.js';
import { proxyFetch } from '../lib/proxy.js';
import { providerTimeoutMs, streamStallTimeoutMs } from '../lib/provider-timeout.js';
import { extractThinkTagsFromStream } from '../lib/think-tags.js';

/** A provider HTTP error carrying the upstream status and, when the provider
 *  stated one, the parsed back-off so the router can bench the key for at least
 *  that long. The delay may come from the Retry-After header or from the error
 *  body — see providerHttpError. */
export interface ProviderHttpError extends Error {
  status?: number;
  retryAfterMs?: number;
  /** Explicit daily-window violation from structured upstream quota details. */
  dailyQuotaExhausted?: boolean;
}

/** Upper bound on a provider-supplied back-off. A malformed or hostile
 *  `Retry-After` (e.g. 99999999999) would otherwise bench a key effectively
 *  forever, since the value feeds the cooldown expiry directly. A day is longer
 *  than any real free-tier reset window, so clamping cannot mask a genuine hint. */
const MAX_RETRY_AFTER_MS = 24 * 60 * 60 * 1000;

/** Parse an HTTP `Retry-After` header (delta-seconds or an HTTP-date) into a
 *  millisecond delay, clamped to MAX_RETRY_AFTER_MS. Returns undefined when
 *  absent or unparseable. */
export function parseRetryAfterMs(value: string | null | undefined): number | undefined {
  if (!value) return undefined;
  const trimmed = value.trim();
  if (/^\d+$/.test(trimmed)) return Math.min(Number(trimmed) * 1000, MAX_RETRY_AFTER_MS);
  const when = Date.parse(trimmed);
  if (!Number.isNaN(when)) {
    return Math.min(Math.max(0, when - Date.now()), MAX_RETRY_AFTER_MS);
  }
  return undefined;
}

/** A protobuf Duration, as google.rpc.RetryInfo spells its `retryDelay`:
 *  digits, an optional fraction, then a literal `s` ("17s", "1.5s", "0.25s"). */
const PROTOBUF_DURATION = /^(\d+(?:\.\d+)?)s$/;

/** "Please try again in 7.66s" / "retry after 30 seconds" / "try again in 2m".
 *  Anchored on an explicit retry phrase so an unrelated number in an error
 *  message can never be mistaken for a back-off. */
const PROSE_RETRY = /(?:try again|retry)\s+(?:in|after)\s+(\d+(?:\.\d+)?)\s*(ms|s|sec|secs|second|seconds|m|min|mins|minute|minutes|h|hour|hours)\b/i;

const UNIT_MS: Record<string, number> = {
  ms: 1,
  s: 1000, sec: 1000, secs: 1000, second: 1000, seconds: 1000,
  m: 60_000, min: 60_000, mins: 60_000, minute: 60_000, minutes: 60_000,
  h: 3_600_000, hour: 3_600_000, hours: 3_600_000,
};

function clampRetryMs(ms: number): number | undefined {
  if (!Number.isFinite(ms) || ms < 0) return undefined;
  return Math.min(ms, MAX_RETRY_AFTER_MS);
}

/** Depth-first search for the first `retryDelay`/`retry_after`-shaped field. The
 *  shape varies by provider and by endpoint within a provider, so walking is
 *  more durable than a list of exact paths — and cheaper to maintain than one
 *  parser per adapter. Depth-capped so a pathological body cannot spin. */
function findStatedDelayMs(node: unknown, depth = 0): number | undefined {
  if (depth > 6 || node === null || typeof node !== 'object') return undefined;

  if (Array.isArray(node)) {
    for (const item of node) {
      const found = findStatedDelayMs(item, depth + 1);
      if (found !== undefined) return found;
    }
    return undefined;
  }

  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
    const normalized = key.toLowerCase().replace(/[_-]/g, '');
    if (normalized === 'retrydelay' || normalized === 'retryafter' || normalized === 'retryafterseconds') {
      // google.rpc.RetryInfo states "17s"; other providers state bare seconds.
      if (typeof value === 'string') {
        const duration = PROTOBUF_DURATION.exec(value.trim());
        if (duration) return clampRetryMs(Number(duration[1]) * 1000);
        if (/^\d+(\.\d+)?$/.test(value.trim())) return clampRetryMs(Number(value) * 1000);
      }
      if (typeof value === 'number') return clampRetryMs(value * 1000);
    }
    const found = findStatedDelayMs(value, depth + 1);
    if (found !== undefined) return found;
  }
  return undefined;
}

/**
 * The back-off a provider stated inside its error BODY, in milliseconds.
 *
 * Not every provider uses the Retry-After header. Gemini answers a 429 with
 * `error.details[]` carrying a `google.rpc.RetryInfo` whose `retryDelay` is
 * "17s", and several OpenAI-compatible tiers only say it in prose. Those hints
 * were being thrown away: the body is flattened to a single message string
 * before it reaches the router, so a provider that told us exactly when to come
 * back got the same heuristic cooldown ladder as one that said nothing.
 */
export function parseStatedRetryMs(body: unknown): number | undefined {
  if (body == null) return undefined;

  if (typeof body !== 'string') {
    const structured = findStatedDelayMs(body);
    if (structured !== undefined) return structured;
  }

  // Prose last: a stated field is a promise, a sentence is an observation.
  const text = typeof body === 'string' ? body : safeStringify(body);
  const prose = text ? PROSE_RETRY.exec(text) : null;
  if (prose) {
    const unit = UNIT_MS[prose[2].toLowerCase()];
    if (unit) return clampRetryMs(Number(prose[1]) * unit);
  }
  return undefined;
}

function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value) ?? '';
  } catch {
    return ''; // Circular or otherwise unserialisable — no prose to read.
  }
}

/** Build an error for a non-OK upstream response, capturing the status and any
 *  stated back-off. Used by every provider adapter so the proxy can honor a
 *  provider's explicit hint when it sets the cooldown.
 *
 *  `body` is the already-parsed error payload the caller used to build
 *  `message`. Only a delay is read out of it and only a number is kept — the
 *  body itself is never retained, so nothing extra reaches a log or the
 *  attempt trace. The Retry-After header still wins when both are present: it
 *  is the standard channel, and preferring it keeps existing behavior exactly
 *  as it was. */
export function providerHttpError(res: Response, message: string, body?: unknown): ProviderHttpError {
  const err = new Error(message) as ProviderHttpError;
  err.status = res.status;
  const retryAfterMs = parseRetryAfterMs(res.headers?.get('retry-after')) ?? parseStatedRetryMs(body);
  if (retryAfterMs !== undefined) err.retryAfterMs = retryAfterMs;
  return err;
}

// Extended sampling knobs (top_k, seed, penalties, logit_bias, logprobs,
// response_format…) ride along via ExtendedSamplingOptions; adapters forward
// them per the platform policy in lib/sampling-params.ts.
export interface CompletionOptions extends ExtendedSamplingOptions {
  model?: string;
  temperature?: number;
  max_tokens?: number;
  top_p?: number;
  stop?: string | string[];
  tools?: ChatToolDefinition[];
  tool_choice?: ChatToolChoice;
  parallel_tool_calls?: boolean;
  stream_options?: {
    include_usage?: boolean;
  };
  /** Remaining context budget (context_window − estimated_input_tokens) for
   *  this route. resolveMaxTokens clamps max_tokens to fit. */
  contextBudget?: number;
  /** Per-call HTTP timeout override. Not part of the OpenAI wire format (it is
   * stripped before the request body is built); used by the probe script so
   * NVIDIA's 15-60s serverless cold starts don't read as failures. */
  timeoutMs?: number;
  /** Abort signal for the gateway's OWN client (request socket closed). The
   * proxy surfaces thread it here so a disconnect cancels the upstream fetch
   * AND any in-progress body/stream read — tokens stop burning and the
   * in-flight lease frees immediately instead of when the read happens to
   * finish. Composed with the per-attempt timeout in fetchWithTimeout; never
   * serialized into the request body. */
  signal?: AbortSignal;
}

/** Per-call abort/timeout wiring for fetchWithTimeout. */
export interface ProviderFetchOptions {
  /** Client-disconnect signal, composed with the per-attempt timeout via
   * AbortSignal.any. Unlike the timeout it is never disarmed at headers, so it
   * also aborts body reads and stream iteration through undici. */
  signal?: AbortSignal;
  /** What the per-attempt timeout bounds:
   *  - 'headers' (default, historical): the abort timer dies the moment
   *    response HEADERS arrive — right for streams, whose body legitimately
   *    outlives any fixed deadline (readSseStream's stall watchdog owns
   *    mid-stream hangs, the client signal owns "nobody is listening").
   *  - 'request': the deadline stays armed across the body read too, so a 200
   *    whose body never finishes aborts at timeoutMs instead of hanging
   *    res.json() forever. Use for non-streaming calls, which read the whole
   *    body as one unit. */
  timeoutBounds?: 'headers' | 'request';
}

/** Per-stream timeout wiring for readSseStream (#584). */
export interface SseStreamOptions {
  /** The chat timeout the adapter gave fetchWithTimeout for this request
   * (options.timeoutMs override included). Becomes the first-byte grace
   * budget, floored at the stall budget — see firstByteBudgetMs. Defaults to
   * fetchWithTimeout's own default, providerTimeoutMs(platform, 15000). */
  firstByteTimeoutMs?: number;
  /** Mid-stream inactivity budget; defaults to streamStallTimeoutMs(platform)
   * (per-platform env > global env > 90s). 0 disables the watchdog. */
  stallTimeoutMs?: number;
}

export interface KeyValidationFailure {
  valid: false;
  /** Provider-supplied reason suitable for health logs and the local keys UI. */
  error: string;
}

export type KeyValidationResult = boolean | KeyValidationFailure;

export abstract class BaseProvider {
  abstract readonly platform: Platform;
  abstract readonly name: string;
  /** Providers whose free tier needs no API key (e.g. Kilo's anonymous gateway).
   * When true, the gateway stores a sentinel key row so routing still considers
   * the platform "configured", and the provider omits the Authorization header
   * on outgoing requests. Defaults to false; set by subclasses. */
  keyless = false;

  abstract chatCompletion(
    apiKey: string,
    messages: ChatMessage[],
    modelId: string,
    options?: CompletionOptions,
    quotaContext?: QuotaObservationContext,
  ): Promise<ChatCompletionResponse>;

  abstract streamChatCompletion(
    apiKey: string,
    messages: ChatMessage[],
    modelId: string,
    options?: CompletionOptions,
    quotaContext?: QuotaObservationContext,
  ): AsyncGenerator<ChatCompletionChunk>;

  abstract validateKey(apiKey: string, quotaContext?: QuotaObservationContext): Promise<KeyValidationResult>;

  /**
   * Optional quota/balance probe (#1403). Providers whose API exposes a
   * key-info/quota endpoint override this to fetch the provider-reported
   * limit/remaining and persist them as a `source: 'quota_api'` observation,
   * so the dashboard shows a real balance instead of a text-label guess.
   * Must never throw into the caller: the default implementation does no
   * network at all and returns false; implementations catch transport errors
   * and return false so a quota probe can never change a health verdict.
   * Returns true when an observation was recorded.
   */
  async fetchQuota(_apiKey: string, _quotaContext?: QuotaObservationContext): Promise<boolean> {
    return false;
  }

  /** Whether this provider actually has a quota endpoint to probe (#1403).
   * fetchQuota alone can't answer it: OpenAICompatProvider overrides the
   * method for every instance, spec or not. Routes that owe the operator a
   * "this platform has no quota endpoint" answer must use this instead. */
  get hasQuotaProbe(): boolean {
    return false;
  }

  /** Whether the health checker may probe this provider's keys at all (#1459).
   * A provider that forbids automated key checks (LLMTR answers any probe with
   * 403 "automated API key validation tools are not supported", and its
   * security system suspends accounts that keep sending them) returns false:
   * the health pass and the cooldown probe then never call validateKey for its
   * keys, and a key is promoted to healthy by the first request it serves
   * (markKeyHealthyFromRequest) instead of by a probe. */
  get supportsKeyValidation(): boolean {
    return true;
  }

  /**
   * Turn a conventional 401/403 validation response into a diagnostic result.
   * Providers still return a simple boolean when no useful error body exists,
   * but preserving the upstream message here lets the health service persist
   * and display the reason instead of reducing every failure to "invalid".
   */
  protected async validationResult(res: Response): Promise<KeyValidationResult> {
    if (res.status !== 401 && res.status !== 403) return true;
    // A Cloudflare bot challenge ("Just a moment...") is a 403 about the
    // caller's IP and User-Agent, not about the key. Surface it as
    // inconclusive so health never auto-disables a good key behind it (#1298).
    if (res.headers?.get('cf-mitigated') === 'challenge') {
      throw providerHttpError(res, `${this.name} key validation blocked by a Cloudflare challenge (HTTP ${res.status}); the key was not checked`);
    }

    let body: any = null;
    try {
      if (typeof (res as any).json === 'function') body = await res.json();
    } catch {
      // A status and provider name are still more useful than no reason.
    }

    const detail = [
      body?.error?.message,
      body?.errors?.[0]?.message,
      body?.message,
      body?.detail,
      body?.title,
      res.statusText,
    ].find((value) => typeof value === 'string' && value.trim().length > 0);

    return {
      valid: false,
      error: `${this.name} key validation failed (HTTP ${res.status})${detail ? `: ${detail}` : ''}`,
    };
  }

  protected async fetchWithTimeout(
    url: string,
    init: RequestInit,
    // Adapters that don't pass a timeout inherit the platform's env override
    // (PROVIDER_TIMEOUT_<PLATFORM>, issue #547) over the historical 15s.
    timeoutMs = providerTimeoutMs(this.platform, 15000),
    fetchOpts?: ProviderFetchOptions,
  ): Promise<Response> {
    const signals: AbortSignal[] = [];
    if (fetchOpts?.signal) signals.push(fetchOpts.signal);

    // timeoutMs <= 0 means "no timeout" (PROVIDER_TIMEOUT_<PLATFORM>=0).
    // setTimeout(abort, 0) would abort every request on the next macrotask.
    let headerTimer: ReturnType<typeof setTimeout> | undefined;
    if (timeoutMs > 0) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      signals.push(controller.signal);
      if (fetchOpts?.timeoutBounds === 'request') {
        // Whole-request deadline: stays armed across the body read, so a 200
        // whose body never finishes aborts res.json() at timeoutMs instead of
        // hanging forever. Never cleared — firing after the response is fully
        // consumed is a no-op — and unref'd so a spent request's leftover
        // deadline can't hold the process open.
        timer.unref?.();
      } else {
        // Historical header-only deadline: disarmed the moment response
        // HEADERS arrive (see finally). Streams need this — an SSE body
        // legitimately outlives any fixed deadline, and mid-stream hangs are
        // owned by the stall watchdog (readSseStream) + the client signal.
        headerTimer = timer;
      }
    }

    // Compose the per-attempt timeout with the client-disconnect signal.
    // Unlike the timeout, the client signal is never disarmed: undici ties it
    // to the whole request, so a disconnect also aborts body reads and stream
    // iteration, rejecting them with the marked reason from newClientAbortError.
    const signal = signals.length === 0
      ? init.signal ?? undefined
      : signals.length === 1 ? signals[0] : AbortSignal.any(signals);

    try {
      // requestType='chat' + timeoutMs makes the AbortError message read
      // `<platform>, chat, 15s` for triage from the requests.error column.
      return await proxyFetch(url, signal ? { ...init, signal } : init, this.platform, 'chat', timeoutMs);
    } finally {
      if (headerTimer !== undefined) clearTimeout(headerTimer);
    }
  }

  protected makeId(): string {
    return `chatcmpl-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  }

  /**
   * One reader.read() bounded by the mid-stream inactivity watchdog (#553).
   * Shared by readSseStream and adapters that parse their own wire format
   * (google.ts) so every stream gets the same stall semantics:
   * PROVIDER_STREAM_STALL_TIMEOUT_MS (per-platform override
   * PROVIDER_STREAM_STALL_TIMEOUT_<PLATFORM>, #584), default 90s, 0 disables.
   * Client-abort rejections pass through untouched — undici errors the body
   * with the request signal's reason, so a disconnect surfaces here as the
   * marked error from newClientAbortError, not as a stall. `timeoutMessage`
   * lets the first-byte read report its distinct wording (#584).
   */
  protected async readWithStallTimeout<T>(
    read: () => Promise<T>,
    inactivityTimeoutMs: number,
    timeoutMessage?: string,
  ): Promise<T> {
    if (inactivityTimeoutMs <= 0) return read();
    let timer: ReturnType<typeof setTimeout> | undefined;
    return Promise.race([
      read(),
      new Promise<never>((_, reject) => {
        timer = setTimeout(
          () => reject(new Error(timeoutMessage ?? `${this.name} stream stalled: no data for ${inactivityTimeoutMs}ms (timeout)`)),
          inactivityTimeoutMs,
        );
      }),
    ]).finally(() => clearTimeout(timer));
  }

  /**
   * Budget for the FIRST read of a streaming body (issue #584): the platform's
   * chat timeout is already "how slow may the first token be" — tuned per
   * platform at registration and env-overridable via PROVIDER_TIMEOUT_<PLATFORM>
   * — but on streams it is disarmed the moment response HEADERS arrive, and
   * providers like NVIDIA NIM send SSE headers instantly then prefill for
   * minutes. Floored at the stall budget so a platform with a short chat
   * timeout never gets a STRICTER first read than the pre-#584 watchdog gave
   * it. 0 on either side (env-disabled chat timeout, or disabled watchdog)
   * means the first read is unbounded — the client signal still owns
   * "nobody is listening".
   */
  protected firstByteBudgetMs(chatTimeoutMs: number, stallTimeoutMs: number): number {
    if (chatTimeoutMs <= 0 || stallTimeoutMs <= 0) return 0;
    return Math.max(chatTimeoutMs, stallTimeoutMs);
  }

  /** Distinct wording for a first-byte timeout (vs a mid-stream stall) so the
   * attempt-trace error_summary tells slow prefill apart from a dead stream. */
  protected firstByteTimeoutMessage(budgetMs: number): string {
    return `${this.name} stream: no first byte within ${budgetMs}ms (first-byte timeout)`;
  }

  /**
   * Shared SSE reader for OpenAI-wire streaming endpoints (#231 audit).
   *
   * Hardened against the upstream failure modes observed live:
   *  - Inactivity timeout: fetchWithTimeout's abort timer dies the moment
   *    response HEADERS arrive, so a provider that stalls mid-body used to
   *    hang the client forever. Each read now has its own deadline. The FIRST
   *    read gets a grace budget derived from the platform's chat timeout
   *    (#584) — SSE headers can arrive instantly while the model prefills a
   *    long prompt for minutes, which is slow, not stalled.
   *  - Abrupt EOF: a stream that ends without `[DONE]` AND without any
   *    `finish_reason` is a truncated generation, not a completion. It used
   *    to end the generator silently (truncation logged as success); it now
   *    throws a retryable error so the proxy can fail over or report it.
   *    Providers that skip `[DONE]` but do send a terminal finish_reason
   *    (several compat shims) still complete normally.
   *
   * Malformed data lines are skipped, matching previous behavior.
   *
   * The frames additionally pass through the inline `<think>` extractor
   * (lib/think-tags.ts): DeepSeek-style models that serialize their reasoning
   * trace INTO delta.content as a leading `<think>…</think>` block get it
   * moved to delta.reasoning_content, so downstream surfaces never render
   * thinking as answer text. Streams without the tag are forwarded verbatim.
   */
  protected async *readSseStream(
    res: Response,
    opts?: SseStreamOptions,
  ): AsyncGenerator<ChatCompletionChunk> {
    yield* extractThinkTagsFromStream(this.readSseFrames(res, opts));
  }

  private async *readSseFrames(
    res: Response,
    opts?: SseStreamOptions,
  ): AsyncGenerator<ChatCompletionChunk> {
    const reader = res.body?.getReader();
    if (!reader) throw new Error('No response body');

    // The 90s default was hardcoded and silently truncated slow streams — the
    // gateway ended them with an error frame plus a clean [DONE] that OpenAI
    // SDK clients swallow, so responses "just stopped" (issue #553). Operators
    // proxying slow free tiers can raise it (or 0 to disable) via
    // PROVIDER_STREAM_STALL_TIMEOUT_MS, or per platform via
    // PROVIDER_STREAM_STALL_TIMEOUT_<PLATFORM> (#584).
    const inactivityTimeoutMs = opts?.stallTimeoutMs ?? streamStallTimeoutMs(this.platform);
    // First-byte grace (#584): adapters pass the same chat timeout they gave
    // fetchWithTimeout; the fallback mirrors fetchWithTimeout's own default so
    // adapters that never tuned either stay on max(15s-or-env, stall) — i.e.
    // exactly the stall budget they had before.
    const chatTimeoutMs = opts?.firstByteTimeoutMs ?? providerTimeoutMs(this.platform, 15000);
    const firstByteMs = this.firstByteBudgetMs(chatTimeoutMs, inactivityTimeoutMs);

    const decoder = new TextDecoder();
    let buffer = '';
    let sawFinishReason = false;
    let awaitingFirstByte = true;

    try {
      while (true) {
        const { done, value } = awaitingFirstByte
          ? await this.readWithStallTimeout(() => reader.read(), firstByteMs, this.firstByteTimeoutMessage(firstByteMs))
          : await this.readWithStallTimeout(() => reader.read(), inactivityTimeoutMs);
        awaitingFirstByte = false;
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed || !trimmed.startsWith('data:')) continue;
          const data = trimmed.slice(5).replace(/^ /, '');
          if (data === '[DONE]') return;
          try {
            const chunk = JSON.parse(data) as ChatCompletionChunk;
            if (chunk.choices?.some(c => c.finish_reason != null)) sawFinishReason = true;
            yield chunk;
          } catch {
            // Skip malformed chunks
          }
        }
      }
    } finally {
      reader.cancel().catch(() => { /* upstream already gone */ });
    }

    if (!sawFinishReason) {
      throw new Error(`${this.name} stream ended unexpectedly (no [DONE], no finish_reason) — connection reset or truncated upstream`);
    }
  }
}

function.description:
show pie or donut charts for categorical data visualization.
Supports one or more charts in a grid layout.
The `data` field must always be an array; pass a single-element array for one chart.

Each chart object must contain:
- values: Array of numbers OR objects with 'label' and 'value'
- type: Optional 'doughnut' (default) or 'pie'
- title: Optional chart title
- labels: Optional array of labels (required when values are plain numbers)

Example single chart (labeled values):
[
  {
    "values": [
      {"label": "Marketing", "value": 25000},
      {"label": "Development", "value": 35000}
    ],
    "title": "Budget"
  }
]

Example single chart (parallel arrays):
[
  {
    "values": [45000, 38000],
    "labels": ["Product A", "Product B"],
    "type": "pie"
  }
]

Example multiple charts (array of chart objects):
[
  {"values": [60, 40], "labels": ["Yes", "No"], "title": "Q1"},
  {"values": [75, 25], "labels": ["Yes", "No"], "title": "Q2"}
]

show a Mermaid diagram from Mermaid syntax

Provide the Mermaid code as a string. Supports flowcharts, sequence diagrams, Gantt charts, etc.

Example:
graph TD;
    A-->B;
    A-->C;
    B-->D;
    C-->D;

show a radar chart (spider chart) for multi-dimensional data comparison

The data must contain:
- labels: Array of strings representing the dimensions/axes
- datasets: Array of dataset objects with 'label' and 'data' properties

Example:
{
  "labels": ["Speed", "Strength", "Endurance", "Agility", "Intelligence"],
  "datasets": [
    {
      "label": "Player 1",
      "data": [85, 70, 90, 75, 80]
    },
    {
      "label": "Player 2",
      "data": [75, 85, 80, 90, 70]
    }
  ]
}

show a Sankey diagram from flow data
The data must contain:
- nodes: Array of objects with 'name' and optional 'category' properties
- links: Array of objects with 'source', 'target', and 'value' properties

IMPORTANT: Links must NOT form cycles (e.g. A→B and B→A). Sankey diagrams are
directional acyclic flows. If the data has circular relationships, restructure
them so flow moves in one direction (e.g. add a separate node like "Re-signed"
instead of linking back to an earlier node).

Example:
{
  "nodes": [
    {"name": "Source A", "category": "source"},
    {"name": "Target B", "category": "target"}
  ],
  "links": [
    {"source": "Source A", "target": "Target B", "value": 100}
  ]
}

show a treemap visualization for hierarchical data with proportional area representation as boxes

The data should be a hierarchical structure with:
- name: Name of the node (required)
- value: Numeric value for leaf nodes (optional for parent nodes)
- children: Array of child nodes (optional)
- category: Category for coloring (optional)

Example:
{
  "name": "Root",
  "children": [
    {
      "name": "Group A",
      "children": [
        {"name": "Item 1", "value": 100, "category": "Type1"},
        {"name": "Item 2", "value": 200, "category": "Type2"}
      ]
    },
    {"name": "Item 3", "value": 150, "category": "Type1"}
  ]
}

show interactive line, scatter, or bar charts

Required: type ('line', 'scatter', or 'bar'), datasets array
Optional: labels, title, subtitle, xAxisLabel, yAxisLabel, options

Example:
{
  "type": "line",
  "title": "Monthly Sales",
  "labels": ["Jan", "Feb", "Mar"],
  "datasets": [
    {"label": "Product A", "data": [65, 59, 80]}
  ]
}

