    try {
      if (typeof (res as any).json === 'function') body = await res.json();
    } catch {
      // A status and provider name are still more useful than no reason.
    }

    const detail = [
      body?.error?.message,
      body?.errors?.[0]?.message,
      body?.message,
      body?.detail,
      body?.title,
      res.statusText,
    ].find((value) => typeof value === 'string' && value.trim().length > 0);

